<script setup lang="ts">
import { computed } from 'vue';
import type { Study } from './model.ts';
const props=defineProps<{study:Study;player?:{x:number;z:number}}>();
defineEmits<{play:[];close:[]}>();
const paths=computed(()=>props.study.roads.map(r=>({id:r.id,points:r.points.map(p=>`${p.x},${p.z}`).join(' ')})));
</script>
<template><section class="network-panel" aria-label="Wukari road network overview"><header><div><p class="eyebrow">BEFORE YOU SET OUT</p><h1>A connected piece of Wukari</h1><p>Real mapped bends and junctions. Follow the roads and choose your turn.</p></div><button @click="$emit('close')" aria-label="Close network overview">×</button></header><svg :viewBox="`${-study.halfSize} ${-study.halfSize} ${study.halfSize*2} ${study.halfSize*2}`" role="img" aria-label="Original connected Wukari road network and virtual start"><polygon v-for="b in study.buildings" :key="b.id" :points="b.points.map(p=>`${p.x},${p.z}`).join(' ')" fill="#c2b39b"/><polyline v-for="road in paths" :key="road.id" :points="road.points" fill="none" stroke="#315e53" stroke-width="4"><title>OSM way {{ road.id }}</title></polyline><circle v-if="player||study.spawn" :cx="player?.x??study.spawn!.point.x" :cy="player?.z??study.spawn!.point.z" r="11" fill="#ce6c38" stroke="#fff" stroke-width="3"/><text x="20" y="-20" fill="#344c3c" font-size="20">Your position / virtual start</text><text :x="-study.halfSize+20" :y="-study.halfSize+35" font-size="24" fill="#315e53">N ↑</text></svg><footer><p>Source-backed town window · access and physical safety unverified.<br>Source conflicts are listed in Map Information. FUW is a separate non-spawning area.</p><button class="primary" @click="$emit('play')">Walk this network</button></footer></section></template>
